import { useCallback, useEffect, useRef, useState } from 'react'
import { getLoginStatus } from '../api'

// Shows the WhatsApp login code generated by the backend's browser session,
// which the person then types into their phone under Linked Devices.
//
// Behaviour notes:
//
// * Polls /api/login-status/ every 2s. The backend is the single source of
//   truth: it clears the code once WhatsApp reports the device linked, and
//   this component detects that by the code disappearing. The old version
//   inferred success locally instead.
//
// * Stops polling on unmount, on reaching a terminal state, and on any
//   callback firing. The old effect listed `onReady`/`onFailed` in its
//   dependency array while the parent recreated those props on every render,
//   so the interval was torn down and rebuilt several times a second for the
//   whole 10-minute login window.
//
// * `everSawCode` is a ref rather than state because it must be readable
//   inside the interval closure without re-triggering the effect — using
//   state here caused the interval to be rebuilt on every code change.
const POLL_INTERVAL_MS = 2000

function LoginCode({ onReady, onFailed }) {
  const [code, setCode] = useState(null)
  const [codeError, setCodeError] = useState(null)
  const [slowNetwork, setSlowNetwork] = useState(false)
  const [hasGaveUp, setHasGaveUp] = useState(false)

  const onReadyRef = useRef(onReady)
  const onFailedRef = useRef(onFailed)
  const everSawCode = useRef(false)
  const settled = useRef(false)

  useEffect(() => {
    onReadyRef.current = onReady
    onFailedRef.current = onFailed
  })

  useEffect(() => {
    let cancelled = false

    const finish = (fn) => {
      if (settled.current) return
      settled.current = true
      if (!cancelled) fn()
    }

    const poll = async () => {
      if (cancelled || settled.current) return
      try {
        const data = await getLoginStatus()
        if (cancelled || settled.current) return

        if (data.login_failed) {
          setCode(null)
          finish(() => onFailedRef.current?.())
          return
        }

        if (data.login_code_error) {
          setCodeError(data.login_code_error)
        }

        if (data.code_ready && data.login_code) {
          everSawCode.current = true
          setSlowNetwork(Boolean(data.login_slow))
          setCode(data.login_code)
        } else if (everSawCode.current) {
          // The code was there and is now gone: the device is linked.
          setCode(null)
          finish(() => onReadyRef.current?.())
        }
      } catch (err) {
        // Transient poll failure. The next tick retries; auth errors are
        // handled globally by the API client.
        if (err?.isUnauthorized) finish(() => onFailedRef.current?.())
      }
    }

    poll()
    const timer = setInterval(poll, POLL_INTERVAL_MS)

    return () => {
      cancelled = true
      clearInterval(timer)
    }
  }, [])

  const dismissError = useCallback(() => {
    setHasGaveUp(true)
  }, [])

  if (hasGaveUp) return null

  // Nothing to say yet — don't render an empty blur over the whole app while
  // the backend is still generating the code.
  if (!code && !codeError) return null

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="login-code-heading"
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 1000,
        background: 'rgba(245, 243, 238, 0.55)',
        backdropFilter: 'blur(6px)',
        WebkitBackdropFilter: 'blur(6px)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 'var(--space-lg)',
      }}
    >
      <div className="bs-card" style={{ textAlign: 'center', maxWidth: '420px' }}>
        {code ? (
          <>
            <h2 id="login-code-heading">Enter this code on your phone</h2>
            <p style={{ marginBottom: 'var(--space-md)' }}>
              Open WhatsApp on your phone → Settings → Linked devices → Link a device → Link with
              phone number instead — then type the code below.
            </p>
            <div
              style={{
                display: 'inline-block',
                fontFamily: 'var(--font-display)',
                fontSize: '28px',
                fontWeight: 500,
                letterSpacing: '4px',
                padding: '16px 28px',
                border: '1px solid var(--border)',
                borderRadius: 'var(--radius-md)',
                background: 'var(--bg-card-muted)',
                color: 'var(--text-primary)',
              }}
            >
              {code}
            </div>

            {slowNetwork && (
              <p style={{ marginTop: 'var(--space-md)', color: 'var(--danger)', fontWeight: 500, fontSize: '13px' }}>
                This is taking a while — check your connection. Still waiting.
              </p>
            )}
          </>
        ) : (
          <>
            <h2 id="login-code-heading">Couldn't generate a login code</h2>
            <p style={{ marginBottom: 'var(--space-md)' }}>
              WhatsApp didn't produce a code in time. This usually means their login page changed
              or the connection dropped — try starting the send again.
            </p>
            <p
              style={{
                fontSize: '12px',
                fontFamily: 'var(--font-display)',
                color: 'var(--danger)',
                background: 'var(--danger-bg)',
                padding: '10px 12px',
                borderRadius: 'var(--radius-sm)',
                textAlign: 'left',
                wordBreak: 'break-word',
              }}
            >
              {codeError}
            </p>
            <button
              onClick={dismissError}
              className="bs-btn bs-btn-secondary"
              style={{ marginTop: 'var(--space-md)', padding: '8px 16px', fontSize: '13px' }}
            >
              Dismiss
            </button>
          </>
        )}
      </div>
    </div>
  )
}

export default LoginCode